from vertexai.preview.generative_models import GenerativeModel
import vertexai

def collect_platform_metadata(project_id: str, location: str, model_name: str, prompt: str):
    """
    Returns model output together with Google Cloud Vertex AI platform metadata.
    """
    vertexai.init(project=project_id, location=location)
    model = GenerativeModel(model_name)
    response = model.generate_content(
        prompt,
        generation_config={"max_output_tokens": 256},
        safety_settings={} # Placeholder to ensure settings can be passed
    )

    # Extract relevant metadata (this can vary based on the actual response structure)
    metadata = {
        "model_name": model_name,
        "project_id": project_id,
        "location": location,
        "usage_metadata": { # Example of hypothetical usage metadata
            "prompt_token_count": response.usage_metadata.prompt_token_count if hasattr(response, 'usage_metadata') else None,
            "candidates_token_count": response.usage_metadata.candidates_token_count if hasattr(response, 'usage_metadata') else None,
            "total_token_count": response.usage_metadata.total_token_count if hasattr(response, 'usage_metadata') else None,
        }
    }

    text_output = ""
    if response.candidates:
        for candidate in response.candidates:
            if candidate.content and candidate.content.parts:
                for part in candidate.content.parts:
                    if hasattr(part, 'text'):
                        text_output += part.text

    return {"text": text_output, "metadata": metadata}

from google.cloud import aiplatform
import vertexai

class VertexAIModelClient:
    def __init__(self, project_id: str, location: str):
        self.project_id = project_id
        self.location = location
        vertexai.init(project=self.project_id, location=self.location)
        self.model_service_client_options = {"api_endpoint": f"{location}-aiplatform.googleapis.com"}

    def get_generative_model(self, model_name: str):
        """
        Returns a GenerativeModel instance.
        """
        from vertexai.preview.generative_models import GenerativeModel
        return GenerativeModel(model_name)

    def get_model_resource_name(self, model_id: str):
        """
        Constructs the full resource name for a model.
        """
        client = aiplatform.gapic.ModelServiceClient(client_options=self.model_service_client_options)
        return client.model_path(self.project_id, self.location, model_id)

import dataclasses
from typing import Any, Dict, List, Optional

@dataclasses.dataclass
class ModelRequest:
    prompt: str
    temperature: Optional[float] = 0.7
    max_output_tokens: Optional[int] = 256

@dataclasses.dataclass
class ModelResponse:
    text: str
    metadata: Optional[Dict[str, Any]] = None

def normalize_vertex_ai_response(vertex_ai_response: Any) -> ModelResponse:
    """
    Normalizes a Google Cloud Vertex AI model response into a standard ModelResponse.
    """
    text_output = ""
    if vertex_ai_response.candidates:
        for candidate in vertex_ai_response.candidates:
            if candidate.content and candidate.content.parts:
                for part in candidate.content.parts:
                    if hasattr(part, 'text'):
                        text_output += part.text

    metadata = {
        "usage_metadata": {
            "prompt_token_count": vertex_ai_response.usage_metadata.prompt_token_count if hasattr(vertex_ai_response, 'usage_metadata') else None,
            "candidates_token_count": vertex_ai_response.usage_metadata.candidates_token_count if hasattr(vertex_ai_response, 'usage_metadata') else None,
            "total_token_count": vertex_ai_response.usage_metadata.total_token_count if hasattr(vertex_ai_response, 'usage_metadata') else None,
        }
    }

    return ModelResponse(text=text_output, metadata=metadata)
